def intersperse_recursive(numbers: List[int], delimeter: int) -> List[int]:
    if not numbers:
        return []

    if len(numbers) == 1:
        return numbers

    result = numbers[:2]
    result[1:1] = [delimeter]

    return result + intersperse_recursive(numbers[2:], delimeter)


def intersperse_slice(numbers: List[int], delimeter: int) -> List[int]:
    """ Slice is used because list.append and list.extend are O(n) operations, list.insert is O(n^2)
    >>> intersperse_slice([], 4)
    []
    >>> intersperse_slice([1, 2, 3], 4)
    [1, 4, 2, 4, 3]
    """
    return [] if not numbers else [n for pair in zip(numbers, [delimeter] * len(numbers)) for n in pair] + [numbers[-1]]

    if not numbers:
        return numbers

    numbers.insert(1, delimeter)
    while len(numbers) > 2:
        numbers.insert(-1, delimeter)
    return numbers


def intersperse_unpack(numbers: List[int], delimeter: int) -> List[int]:
    """ Insert a number 'delimeter' between every two consecutive elements of input list `numbers'
    >>> intersperse_unpack([], 4)
    []
    >>> intersperse_unpack([1, 2, 3], 4)
    [1, 4, 2, 4, 3]
    """
    return list(
        nums for number in numbers for nums in ([number, delimeter] if number != numbers[-1] else [number])
    )


