def get_depth(parens: str) -> int:
    """
    Simple logic, if we see open bracket add 1 to our level and if we see closed one subtract 1.
    """
    depth = 0
    max_depth = 0
    for char in parens:
        if char == '(':
            depth += 1
        else:
            depth -= 1

        if depth > max_depth:
            max_depth = depth
    return max_depth


