    (4, 1)
    """
    if len(numbers) == 0:
        return (None, None)
    else:
        max = numbers[0]
        min = numbers[0]
        for num in numbers:
            if num > max:
                max = num
            if num < min:
                min = num
        return (max, min)


def find_median(numbers: List[int]) -> int:
    """ For a given list of integers, return a median of all the integers in a list.
    >>> find_median([])
    None
    >>> find_median([1, 2, 3, 4])
    2.5
    >>> find_median([1, 2, 3, 4, 5])
    3
    """
    if len(numbers) == 0:
        return None
    else:
        sorted_numbers = sorted(numbers)
        mid = len(sorted_numbers) // 2
        if len(sorted_numbers) % 2 == 0:
            return (sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2
        else:
            return sorted_numbers[mid]


