    2.5
    >>> find_mean([1, 2, 3, 4, 5])
    3.0
    """
    if len(numbers) == 0:
        return 0.0
    else:
        sum = 0
        for num in numbers:
            sum += num
        return sum / len(numbers)


def find_mode(numbers: List[int]) -> int:
    """ For a given list of integers, return a mode of all the integers in a list.
    >>> find_mode([])
    None
    >>> find_mode([1, 2, 3, 4])
    1
    >>> find_mode([1, 2, 3, 4, 5])
    3
    """
    if len(numbers) == 0:
        return None
    else:
        counts = {}
        for num in numbers:
            if num not in counts:
                counts[num] = 1
            else:
                counts[num] += 1
        max_count = max(counts.values())
        for num, count in counts.items():
            if count == max_count:
                return num


