def modexp(a: int, d: int, n: int) -> int:
    """ Calculate a ** d mod n
    >>> modexp(2, 3, 5)
    3
    >>> modexp(4321, 1234, 11)
    10
    """
    if d == 0:
        return 1
    elif d % 2 == 1:
        return (a * modexp(a, d - 1, n)) % n
    else:
        return modexp((a * a) % n, d // 2, n)


