    False
    """
    if greatest_common_divisor(a, b) == 1:
        return True
    else:
        return False


def find_mod_inverse(a: int, n: int) -> int:
    """ Return the modular inverse of a mod n if one exists.
    >>> find_mod_inverse(7, 4)
    3
    >>> find_mod_inverse(17, 3120)
    2753
    """
    for i in range(1, n):
        if modexp(a, i, n) == 1:
            return i
    return -1


