def count_palindromes(string: str) -> int:
    """ Count the number of palindromes in a string.
    >>> count_palindromes('bob')
    1
    >>> count_palindromes('racecar')
    1
    """
    count = 0
    for i in range(len(string)):
        for j in range(i, len(string)):
            if string[i:j+1] == string[i:j+1][::-1]:
                count += 1
    return count

def count_anagrams(string: str) -> int:
    """ Count the number of anagrams in a string.
    >>> count_anagrams('abc')
    3
    >>> count_anagrams('abab')
    3
    """
    count = 0
    for i in range(len(string)):
        for j in range(i, len(string)):
            if sorted(string[i:j+1]) == sorted(string[j+1:]):
                count += 1
    return count

def count_polindromic_anagrams(string: str) -> int:
    """ Count the number of polindromic anagrams in a string.
    >>> count_polindromic_anagrams('abc')
    1
    >>> count_polindromic_anagrams('abab')
    3
    """
    count = 0
    for i in range(len(string)):
        for j in range(i, len(string)):
            if sorted(string[i:j+1]) == sorted(string[j+1:]) and string[i:j+1] == string[i:j+1][::-1]:
                count += 1
    return count

def count_unique_substrings(string: str) -> int:
    """ Count the number of unique substrings in a string.
    >>> count_unique_substrings('abc')
    6
    >>> count_unique_substrings('abab')
    7
    """
    substrings = set()
    for i in range(len(string)):
        for j in range(i, len(string)):
            substrings.add(string[i:j+1])
    return len(substrings)

def count_unique_polindromic_substrings(string: str) -> int:
