    return len(substrings)

def count_unique_polindromic_substrings_with_length(string: str, length: int) -> int:
    """ Count the number of unique polindromic substrings in a string with length equal to length.
    >>> count_unique_polindromic_substrings_with_length('abc', 3)
    1
    >>> count_unique_polindromic_substrings_with_length('abab', 2)
    2
    """
    substrings = set()
    for i in range(len(string) - length + 1):
        substring = string[i:i+length]
        if substring == substring[::-1]:
            substrings.add(substring)
    return len(substrings)

