def convert_to_morse_code(music_notes: List[int]) -> str:
    """ This function takes a list of integers representing musical notes and returns a string
    representing the same notes in Morse code.

    Here is a legend:
    4 - represents whole note 'o', lasts four beats
    2 - represents half note 'o|', lasts two beats
    1 - represents quater note '.|', lasts one beat

    >>> convert_to_morse_code([4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4])
    'o o| .| o| o| .| .| .| .| o o'
    """
    morse_code = ''
    for note in music_notes:
        if note == 4:
            morse_code += 'o '
        elif note == 2:
            morse_code += 'o| '
        elif note == 1:
            morse_code += '.| '
    return morse_code.strip()

