def how_many_times_generator(string: str, substring: str) -> int:
    """ Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> how_many_times_generator('', 'a')
    0
    >>> how_many_times_generator('aaa', 'a')
    3
    >>> how_many_times_generator('aaaa', 'aa')
    3
    """
    if len(substring) == 0:
        yield len(string) + 1
    if len(string) == 0:
        yield 0
    if substring[0] == string[0]:
        yield from how_many_times_generator(string[1:], substring) + how_many_times_generator(string[1:], substring[1:])
    yield from how_many_times_generator(string[1:], substring)

