def binary_search_6(a, low, high, x):
    """ Iterative binary search, (not recursive)
    Find index of given x, if x is not present in given array,
    then return -1

    Example: Input: [2, 3, 4, 10, 40] -> x = 10; Output: 3
    """
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            return mid
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binary_search_7(a, low, high, x):
    """ Recursive binary search
    Find index of given x, if x is not present in given array,
    then return -1

    Example: Input: [2, 3, 4, 10, 40] -> x = 10; Output: 3
    """
    if low > high:
        return -1
    mid = (low + high) // 2
    if a[mid] == x:
        return mid
    if a[mid] > x:
        return binary_search_7(a, low, mid-1, x)
    else:
        return binary_search_7(a, mid+1, high, x)

