def fib(n: int):
    """Return nth value of fibonacci numbers.
    >>> fib(1)
    1
    >>> fib(3)
    2
    >>> fib(6)
    8
    """
    if n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        return fib(n-1) + fib(n-2)


def factorial(n: int):
    """Return factorial of n.
    >>> factorial(1)
    1
    >>> factorial(3)
    6
    >>> factorial(6)
    720
    """
    if n == 1:
        return 1
    else:
        return n * factorial(n-1)


def change_coins(n: int, coins=[5, 3, 1]):
    """Return the minimum coins necessary to make change on n.
    >>> change_coins(10)
    2
    >>> change_coins(14)
    4
    >>> change_coins(5)
    1
    """
    if n < coins[0]:
        return change_coins(n, coins[1:])
    if n >= coins[0]:
        return 1 + change_coins(n-coins[0], coins)


