def sum_of_digits(n: int):
    """Return the sum of digits of a given number.
    >>> sum_of_digits(1)
    1
    >>> sum_of_digits(100)
    1
    >>> sum_of_digits(4224)
    12
    """
    if n < 10:
        return n
    else:
        return n % 10 + sum_of_digits(n // 10)


