    """Return the number of zeroes in a given number.
    >>> count_zeroes(10010)
    2
    >>> count_zeroes(908002001)
    4
    >>> count_zeroes(99999)
    0
    """
    if n < 10:
        if n == 0:
            return 1
        else:
            return 0
    else:
        if n % 10 == 0:
            return 1 + count_zeroes(n // 10)
        else:
            return count_zeroes(n // 10)


