def binary_search_help(l: list, target: int, start: int, end: int):
    """Return the index of target in l, or None if target is not in l.
    (Assumes l is already sorted.)
    Only consider indices from start to end - 1. """
    # Base case: empty list
    if end - start <= 0:
        return None
    # Recursion step: consider the middle index
    mid = (start + end) // 2
    if l[mid] == target:
        return mid
    elif target < l[mid]:
        return binary_search_help(l, target, start, mid)
    else:
        return binary_search_help(l, target, mid + 1, end)

def fast_exponentiation(b: int, n: int):
    """Return b to the nth power. """
    if n == 0:
        return 1
    elif n % 2 == 0:
        return fast_exponentiation(b * b, n // 2)
    else:
        return fast_exponentiation(b, n - 1) * b

