def compute_hcf_help(x: int, y: int, hcf: int):
    """ Return highest common factor of x and y.
    >>> compute_hcf_help(60, 48, 48)
    12
    """
    # Base case: found hcf
    if hcf == 1 or hcf == 0 or (x % hcf == 0 and y % hcf == 0):
        return hcf
    # Recursion step: try hcf - 1
    else:
        return compute_hcf_help(x, y, hcf - 1)

