def n_k_trees(n: int, k: int):
    """Return number of different k-ary trees with n nodes."""
    assert n >= 0, "Number of nodes must be non-negative"
    assert k >= 0, "Number of children must be non-negative"
    if k == 0:
        if n == 0:
            return 1
        else:
            return 0
    if k == 1:
        if n == 0:
            return 1
        else:
            return 1
    if n == 0:
        return 1
    else:
        result = 0
        for i in range(n):
            result += n_k_trees(i, k) * n_k_trees(n - 1 - i, k)
        return result

