def is_balanced_brackets(s: str) -> bool:
    """
    Checks if string of brackets is well formed
    """
    opening_bracket = "("
    closing_bracket = ")"
    bracket_stack = deque()

    for bracket in s:
        if bracket == opening_bracket:
            bracket_stack.append(bracket)
        elif bracket == closing_bracket:
            if len(bracket_stack) == 0:
                return False
            else:
                bracket_stack.pop()

    if len(bracket_stack) == 0:
        return True
    else:
        return False


def is_palindromic(s: str) -> bool:
    """
    Returns True if the string is a palindrome and False otherwise
    """
    from collections import deque
    str_to_deque = deque()
    for char in s:
        str_to_deque.append(char)

    is_palindrome = True
    while len(str_to_deque) > 1 and is_palindrome:
        if str_to_deque.popleft() != str_to_deque.pop():
            is_palindrome = False
    return is_palindrome


