def get_ci_95_mean(l: list):
    """Return 95% confidence interval for the mean of elements in the list l."""
    m = mean(l)
    s = standard_deviation(l)
    n = len(l)
    z = 1.96
    return (m - z * s / n ** 0.5, m + z * s / n ** 0.5)


