def find_2_mods(n: int) -> typing.List[int]:
    """Find all mod p results of 2^n, where p < n."""
    return [modp(n, p) for p in range(1, n)]


def find_2_hack(n: int) -> typing.Optional[Hack]:
    """Try to find a hack for the number n.
    >>> find_2_hack(1)
    2 ^ 1 mod 1 = 0
    >>> find_2_hack(3)
    2 ^ 3 mod 3 = 8
    """
    # 1 is the only "hack" that isn't prime.
    if n == 1:
        return Hack(n, 1)

    mods = find_2_mods(n)

    for i in range(len(mods)):
        if not is_prime(mods[i]):
            continue
        hack = Hack(n, mods[i])
        return hack

    return None


