def least_common(l1: list, l2: list):
    """Return sorted unique common elements for two lists.
    >>> least_common([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 9, 653, 121])
    [1, 5, 653]
    >>> least_common([5, 3, 2, 8], [3, 2])
    [2, 3]

    """
    return sorted(set(l1).symmetric_difference(set(l2)))


def distinct(l1: list, l2: list):
    """Return sorted unique elements that are distinct to both lists.
    >>> distinct([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 9, 653, 121])
    [3, 34, 4, 653, 7, 9, 121]
    >>> distinct([5, 3, 2, 8], [5, 3])
    [2, 8]

    """
    s1 = set(l1)
    s2 = set(l2)
    return sorted(s1.union(s2).difference(s1.intersection(s2)))

def group_sum(l1: list, l2: list, limit: int):
    """
    Return list of unique combinations of numbers from two lists, that sum to a specific limit
    >>> group_sum([5, 3, 2, 8], [4, 6], 11)
    [(3, 8), (3, 4, 4), (4, 6, 4), (5, 6), (5, 4, 4)]
    >>> group_sum([5, 3, 2, 8], [4, 6], 8)
    [(5, 3), (5, 3, 4, 4), (2, 6, 4), (2, 6, 6)]
    """
    # first create a map of lists of all unique sum tuples per count
    # e.g. sum = 3 can be reached with 1 (2,1) or 2 (1,1,1)
    counts = {}
    for l in (l1, l2):
        for s in range(1, limit):
            items = set()
            for i in range(0, len(l)):
                for j in range(i+1, len(l)):
                    for k in range(j+1, len(l)):
                        for m in range(k+1, len(l)):
                            item = (l[i], l[j], l[k], l[m])
                            item_sum = sum(item)
                            if item_sum == s:
                                items.add(item)
            if len(items) > 0:
                counts[s] = items

    # now combine all items until we hit the limit
    # e.g. if limit is 5 we will check all combinations for sum of 1 + 2 + 3 + 4
    sum_items = {}
    for s in range(1, limit + 1):
        if s in counts.keys():
            items = counts[s]
            if len(items) > 0:
                sum_items[s] = items

    groups = {}
    for l in range(1, limit):
        for s in range(1, limit):
            if l + s == limit:
                if s in sum_items.keys():
                    for item1 in sum_items[s]:
                        for item2 in sum_items[l]:
                            merged = tuple(sorted(item1 + item2))
                            if len(merged) == limit:
                                groups[limit] = groups.get(limit, set())
                                groups[limit].add(merged)

    return groups.get(limit, [])

