    """
    Given list lst, of lists with different number of elements,
    create a matrix filled by zeros, where each row contains
    one integer in lst.

    Examples:
    get_columns([1,2,3]) == [[1], [2], [3]]
    get_columns([4,5]) == [[4], [5]]
    get_columns([3,7,5,6,9,1]) == [[3], [7], [5], [6], [9], [1]]
    """
    max_len = max(len(row) for row in lst)
    matrix = [[0] * max_len for _ in range(len(lst))]
    for row in range(len(lst)):
        for col in range(len(lst[row])):
            matrix[row][col] = lst[row][col]
    return matrix

