    """
    Given list lst, of lists with different number of elements,
    find the list of prime numbers in it.

    Examples:
    find_prime_numbers([3,4,5]) == [3, 5]
    find_prime_numbers([4,5]) == [5]
    find_prime_numbers([3,7,5,6,9,1]) == [3, 5, 7]
    """
    primes = []
    for num in lst:
