    Find the list of prime numbers below n.

    Examples:
    get_primes(10) == [2, 3, 5, 7]
    get_primes(5) == [2, 3]
    get_primes(4) == [2, 3]
    """
    primes = []
    for num in range(2, n):
        for i in range(2, num):
            if (num % i) == 0:
                break
        else:
            primes.append(num)
    return primes

