def get_product_of_all_other_numbers(numbers):
    """Given a list of integers, return a list of the products
    of all other numbers except the number at that index.

    For example:
    get_product_of_all_other_numbers([1, 7, 3, 4]) == [84, 12, 28, 21]

    get_product_of_all_other_numbers([1, 2, 6, 5, 9]) == [540, 270, 90, 108, 60]

    get_product_of_all_other_numbers([1, 2, 6, 0, 5, 9]) == [0, 0, 0, 540, 0, 0]

    """

    if 0 in numbers:
        index = numbers.index(0)
        products = [0] * len(numbers)
        product = 1
        for num in numbers:
            if num != 0:
                product *= num
        products[index] = product
        return products

    product = 1
    for num in numbers:
        product *= num
    products = [product / num for num in numbers]

    return products


