    """Produce the set of common elements between two lists of numbers
    Example:
        common_elements([1, 2, 3, 4], [1, 2]) -> {1, 2}
        common_elements([1, 2, 3, 4], [3, 4, 5, 6]) -> {3, 4}
        common_elements([1, 2, 3, 4], [5, 6, 7, 8]) -> set()
        common_elements([1, 2, 1], [1, 2]) -> {1, 2}
    """

    set1 = set(nums1)
    set2 = set(nums2)
    return set1.intersection(set2)


