def minimum_steps_to_zero(num):
    """Return the minimum number of steps to reach a number equal to zero.
    For each step down, divide the number by 2 (if it's even) or subtract 1 (if it's odd).

    For example:
        minimum_steps_to_zero(12) -> 4
        minimum_steps_to_zero(6) -> 2
        minimum_steps_to_zero(14) -> 6

    """

    steps = 0
    while num > 0:
        if num % 2 == 0:
            num /= 2
        else:
            num -= 1
        steps += 1
    return steps


def make_numbers_consecutive(nums):
    """Return the minimum number of integers needed to make a list of numbers consecutive.
    Examples:
        make_numbers_consecutive([4, 8, 6]) -> 2
        make_numbers_consecutive([1, 2, 3, 4]) -> 0
        make_numbers_consecutive([]) -> 0
    """

    if not nums:
        return 0
    nums.sort()
    consecutive_nums = set(range(nums[0], nums[-1] + 1))
    return len(consecutive_nums - set(nums))


