def get_maximum_k1(arr, k):
    """
    Sorts the array and returns the first k elements.  The runtime of the sort 
    is N*log(N) and the retrieval is O(k).  The combined runtime is then 
    N*log(N) + O(k).

    """
    arr.sort(reverse=True)
    return arr[:k]

def get_maximum_k2(arr, k):
    """
    Returns the first k elements from a max heap.  The runtime is k*log(N) as
    each of the first k elements need to be popped from the heap.

    """
    h = MaxHeap()
    h.heap = arr[:]
    h.build_heap()
    return h.k_largest(k)

def get_maximum_k3(arr, k):
    """
    Implements a quickselect and returns the first k elements from the array. 

    """
    def quickselect(arr, i):
        pivot = arr[0]
        low, equal, high = [], [], []
        for val in arr:
            if val < pivot:
                low.append(val)
            elif val == pivot:
                equal.append(val)
            else:
                high.append(val)
        j = len(low)
        if i < j:
            return quickselect(low, i)
        elif i <= j + len(equal):
            return equal
        else:
            return high + quickselect(low, i - j - len(equal))
    return quickselect(arr, k)

