def checkdigit(ean):
    """Create a function which takes an 8-digit number and returns a 12-digit number
    by adding a checksum to the given number.
    The checksum to be added is the difference between 9 and the remainder of the 
    sum of the odd-positioned and even-positioned digits of the number, mod 9.
    Examples:
    checkdigit(7635238) # => 763523810908
    checkdigit(7145678) # => 714567820904
    """
    checkdigit = 9 - (sum(int(ean[i]) for i in range(len(ean))) % 9)
    return int(ean + str(checkdigit) + str(checkdigit))

