def digits_rotations(n):
    '''
    A number with rotational symmetry must look the same, given rotation by 180 degrees or not.
    Write a function that takes an integer n and returns True if the 
    integer is the same after a 180 degrees rotation.
    Examples
    digits_rotations(100) ==> False
    digits_rotations(196) ==> True
    digits_rotations(1231) ==> False
    digits_rotations(8588) ==> True
    digits_rotations(6518) ==> True
    '''
    rotations = {0:0, 1:1, 2:5, 5:2, 8:8}
    rotated = 0
    multiplier = 1
    while n > 0:
        digit = n % 10
        if digit not in rotations:
            return False
        else:
            rotated += rotations[digit] * multiplier
            multiplier *= 10
            n //= 10
    return rotated == n

