def find_unique_sums(n):
    """
    Write a function called find_unique_sums that finds the count of unique sums that can be made from the first n positive integers, if any number can be used as many times as needed.
    """
    num = range(1,n+1)
    a = []
    unique = 0
    for i in range(len(num)):
        for j in range(i,len(num)):
            a.append(num[i]+num[j])
    b = set(a)
    for i in range(1,n+1):
        for j in b:
            if j == i:
                unique += 1
    return unique


