@dataclass
class HashedString:
    """A string that has been hashed using md5."""

    text: str
    hash: str

    @classmethod
    def from_string(cls, text: str) -> 'HashedString':
        """Create a HashedString from a string."""
        hash = string_to_md5(text)
        return cls(text, hash)

    def __repr__(self) -> str:
        return f"HashedString(text={self.text}, hash={self.hash})"


def generate_salt(length: int = 10) -> str:
    """Generate a random salt of the specified length."""
    return ''.join(random.choices(string.ascii_letters + string.digits, k=length))


def hash_string(text: str, salt: str = None) -> HashedString:
    """Hash a string using md5 and a random salt."""
    if salt is None:
        salt = generate_salt()
    return HashedString.from_string(salt + text)


def compare_strings(hash1: HashedString, hash2: HashedString) -> bool:
    """Compare two HashedStrings."""
    return hash1.text == hash2.text and hash1.hash == hash2.hash


def check_hash(text: str, hashed_text: str) -> bool:
    """Check if a string matches its hashed version."""
    hashed_text_obj = HashedString.from_string(hashed_text)
    text_obj = HashedString.from_string(text)
    return compare_strings(text_obj, hashed_text_obj)


def main():
    """Generate a random salt, hash a string, and compare the hashes."""
    salt = generate_salt()
    text = 'Hello world'
    hashed_text = hash_string(text, salt).hash
    print(f"Original text: {text}")
    print(f"Salt: {salt}")
    print(f"Hashed text: {hashed_text}")
    print(f"Check if original text matches hashed text: {check_hash(text, hashed_text)}")


